g(1) = 4*x(1) - 2*x(2) - 2;
g(2) = -2*x(1) + 2*x(2) + 4*(x(2) - x(3)).^3;
g(3) = -4*(x(2) - x(3)).^3;
end

function c = HS60_c(x)
c = zeros(1, 1);
c(1) = x(1).*(x(2).^2 + 1) + x(3).^4 - 3*sqrt(2) - 4;
end

function J = HS60_J(x)
